1	// Ask Atlas OFF/MOCK contracts (docs/stage5/ask/02_CONTRACTS.md, 03_SECURITY_AND_STATE.md). Plain TypeScript, no enums,
2	// so every module runs under --experimental-strip-types. Errors carry a fixed code only: never a message, detail or input.
3	
4	export const ASK_ERROR_CODES = [
5	  'ASK_REQUEST_INVALID', 'ASK_SCOPE_DENIED', 'ASK_AUTHENTICATION_FAILED', 'ASK_CONTEXT_UNAVAILABLE', 'ASK_TOO_LARGE',
6	  'ASK_SCOPE_CHANGED', 'ASK_BUSY', 'ASK_DEADLINE', 'ASK_PLANNER_INVALID', 'ASK_AUDIT_FAILED', 'ASK_RUNTIME_NOT_READY', 'ASK_SOURCE_INVALID'
7	] as const;
8	export type AskErrorCode = typeof ASK_ERROR_CODES[number];
9	
10	/** Fixed HTTP status of every Ask error code (02 "Fixed HTTP surface"). */
11	export const ASK_HTTP_STATUS: Readonly<Record<AskErrorCode, number>> = Object.freeze({
12	  ASK_REQUEST_INVALID: 400, ASK_SCOPE_DENIED: 403, ASK_AUTHENTICATION_FAILED: 401, ASK_CONTEXT_UNAVAILABLE: 404, ASK_TOO_LARGE: 413,
13	  ASK_SCOPE_CHANGED: 409, ASK_BUSY: 429, ASK_DEADLINE: 504, ASK_PLANNER_INVALID: 503, ASK_AUDIT_FAILED: 503, ASK_RUNTIME_NOT_READY: 503,
14	  ASK_SOURCE_INVALID: 503
15	});
16	
17	/** A decided Ask failure. Only the fixed code exists; the message is the code itself, never input or an upstream error. */
18	export class AskFailure extends Error {
19	  readonly code: AskErrorCode;
20	  constructor(code: AskErrorCode) { super(code); this.name = 'AskFailure'; this.code = code; }
21	}
22	export function askFailure(code: AskErrorCode): never { throw new AskFailure(code); }
23	export const isAskFailure = (error: unknown): error is AskFailure => error instanceof AskFailure;
24	
25	/** Approved limits. Raw16KiB and the question's 2000 code points are independent caps. */
26	export const ASK_LIMITS = Object.freeze({
27	  questionCodePoints: 2000, rawBodyBytes: 16 * 1024, responseBytes: 256 * 1024, observationIdLength: 256,
28	  observationPage: 100, graphRows: 1000, resources: 100, resourceItems: 1000, contextBytes: 4 * 1024 * 1024,
29	  bankFacts: 32, bankObservations: 24, bankResources: 7, planRefs: 8, reasonCodes: 100, displayCodePoints: 4000,
30	  deadlineMs: 8000, phaseMs: 2000, poolWaitMs: 500, plannerMs: 2000,
31	  globalOwners: 4, actorEntries: 64, rollingQuestions: 10, rollingWindowMs: 60_000
32	});
33	
34	/** Canonical lowercase UUIDv4 (requestId input and every server correlation ID). Uppercase is rejected. */
35	export const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
36	
37	export const ASK_SOURCES = ['atera', 'huntress'] as const;
38	export type AskSource = typeof ASK_SOURCES[number];
39	export type SourceMode = 'fixture' | 'db';
40	export const ASK_INTENTS = ['SUMMARY', 'WHY_URGENT', 'SOURCE_STATE', 'ENTITY', 'UNSUPPORTED'] as const;
41	export type AskIntent = typeof ASK_INTENTS[number];
42	export type AskStatus = 'ANSWER' | 'INSUFFICIENT' | 'UNSUPPORTED';
43	export const CLAIM_CODES = [
44	  'OBSERVATION_RECORDED', 'RESOURCE_RECORDED', 'SOURCE_URGENT', 'SOURCE_NOT_URGENT_IN_READ', 'ENTITY_CONFIRMED', 'ENTITY_UNRESOLVED', 'ENTITY_UNAVAILABLE'
45	] as const;
46	export type ClaimCode = typeof CLAIM_CODES[number];
47	export type FactKind = 'OBSERVATION' | 'RESOURCE_STATE' | 'ENTITY';
48	export type EntityState = 'CONFIRMED' | 'UNRESOLVED' | 'UNAVAILABLE';
49	
50	/** OBSERVATION data: the accepted ObservationSummary fields (ID renamed observationId), explicit keys in this order. */
51	export interface ObservationData {
52	  observationId: string; source: AskSource; resourceType: string; connectionId: string; externalEventId: string; summary: string;
53	  severity: string; priority: string; route: string; confidence: number; reasonCodes: string[]; status: string; entityId: string | null;
54	  conflictOfEventKey: string | null; supersededById: string | null; occurredAt: string; createdAt: string; updatedAt: string;
55	  acknowledgedAt: string | null; resolvedAt: string | null;
56	}
57	/** RESOURCE_STATE data: accepted ResourceView semantics with an explicit non-null connection; never items. */
58	export interface ResourceData {
59	  source: AskSource; resourceType: string; connectionId: string; status: string; asOf: string | null; lastSuccessAt: string | null; truncated: boolean;
60	}
